export const board = (at, to = 'done', extra = {}) => ({
  eventId: 'board-choice',
  at,
  uncertaintyMs: 2000,
  from: 'idea',
  to,
  resolves: false,
  ...extra,
});

export const phone = (at, to = 'researching', extra = {}) => ({
  entryId: `audit-${at}`,
  at,
  actor: 'owner',
  reason: null,
  from: 'idea',
  to,
  ...extra,
});

export const input = ({
  status = 'idea', base = 'idea', state = 'linked', events = [],
  tags = ['idea'], entries = [], coverage = 'complete', exists = true,
  since,
} = {}) => ({
  card: {
    status, discordBase: base, discordState: state, boardEvents: events,
    ...(since === undefined ? {} : { conflictSince: since }),
  },
  remote: { exists, statusTags: tags },
  audit: { coverage, entries },
});

const b = board(10000);
const early = phone(4000);
const late = phone(16000);
const roundtrip = (at) => [
  phone(at - 3000),
  phone(at, 'idea', { from: 'researching' }),
];
const bot = (at, to, reason = 'unrelated') => phone(at, to, { actor: 'bot', reason });
const resolving = board(20000, 'done', { resolves: true });
const conflicted = { state: 'conflict', status: 'done', since: 10000 };
const invalid = { state: 'invalid', status: 'done', since: 10000 };

// Pure decision data: expected actions are specified before reconcile exists.
